from __future__ import annotations

import re
from datetime import date
from fastapi.responses import HTMLResponse
from .provider_accounts import active_account
from .provider_accounts_panel import provider_accounts_page
from .web import dashboard_html

_CARD='''<div class="card" id="surebet-section"><div class="section-title"><h2>💰 SUREBET · CENTRO ÚNICO</h2><span class="eyebrow">Oportunidades + cálculo automático</span></div><p class="muted">La calculadora aparece solo cuando existe una surebet válida.</p><div class="surebet-scope"><button id="scope-peru" onclick="setSurebetScope('peru')">🇵🇪 PERÚ</button><button id="scope-world" onclick="setSurebetScope('world')">🌎 MUNDIAL</button><button id="scope-all" onclick="setSurebetScope('all')">🌐 TODO</button></div><div class="surebet-buttons"><button id="surebet-pre-button" onclick="loadSurebetPre()">📅 SUREBET PRE-PARTIDO</button><button id="surebet-live-button" class="live-button" onclick="loadSurebetLive()">🔴 SUREBET LIVE · BUSCAR AHORA</button></div><div class="surebet-filters"><label>LIGA <select id="surebet-league" onchange="applyLeagueFilter()"><option value="">TODAS LAS LIGAS</option></select></label></div><div class="status muted" id="surebet-status">Preparando SUREBET...</div><div id="surebet-summary" class="surebet-summary"></div><div id="surebet" class="muted">Cargando oportunidades...</div></div>'''

_JS=r'''const SB={scope:'peru',data:null};const sb$=id=>document.getElementById(id);const escSB=v=>String(v??'').replace(/[&<>\'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));const money=v=>'S/ '+Number(v||0).toLocaleString('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2});const pct=v=>(Number(v||0)*100).toFixed(2)+'%';function scopeLabel(){return SB.scope==='peru'?'🇵🇪 PERÚ':SB.scope==='world'?'🌎 MUNDIAL':'🌐 TODO'}function setSurebetScope(s){SB.scope=s;['peru','world','all'].forEach(x=>{const b=sb$('scope-'+x);if(b)b.classList.toggle('active',x===s)});if(SB.data)renderSurebet(SB.data)}function sbBusy(v){['surebet-pre-button','surebet-live-button'].forEach(id=>{const b=sb$(id);if(b)b.disabled=v})}function calculator(o){const t=o.target_profits||{};const ks=[250,500,1000,3000];const valid=ks.filter(k=>t[k]||t[String(k)]);if(!valid.length)return '';return `<div class="calc-title">🧮 CALCULADORA AUTOMÁTICA · GANANCIA GARANTIZADA</div><table class="calc-table"><thead><tr><th>Ganancia objetivo</th><th>Capital</th><th>Retorno</th><th>Ganancia</th><th>ROI</th></tr></thead><tbody>${valid.map(k=>{const x=t[k]||t[String(k)];return `<tr><td><b>${money(k)}</b></td><td>${money(x.total_stake)}</td><td>${money(x.total_return)}</td><td class="profit">${money(x.guaranteed_profit)}</td><td>${Number(x.roi_percent||0).toFixed(2)}%</td></tr>`}).join('')}</tbody></table>`}function renderSurebet(d){SB.data=d||{};const box=sb$('surebet'),summary=sb$('surebet-summary'),sel=sb$('surebet-league');let rows=Array.isArray(SB.data.opportunities)?SB.data.opportunities.slice():[];const unique=new Map();rows.forEach(x=>{const key=[x.match,x.competition,x.market,x.line??'',x.mode].join('|').toLowerCase();if(!unique.has(key))unique.set(key,x)});rows=[...unique.values()];const leagues=[...new Set(rows.map(x=>x.competition).filter(Boolean))].sort();const old=sel?.value;if(sel){sel.innerHTML='<option value="">TODAS LAS LIGAS</option>'+leagues.map(x=>`<option value="${escSB(x)}">${escSB(x)}</option>`).join('');if(leagues.includes(old))sel.value=old}if(sel?.value)rows=rows.filter(x=>String(x.competition||'').toLowerCase().includes(sel.value.toLowerCase()));summary.innerHTML=`<div class="metric"><span>ÁMBITO</span><b>${scopeLabel()}</b></div><div class="metric"><span>SUREBETS</span><b>${rows.length}</b></div><div class="metric"><span>MODO</span><b>${SB.data.mode==='live'?'🔴 LIVE':'📅 PRE-MATCH'}</b></div>`;if(!rows.length){box.innerHTML='<div class="empty-surebet"><b>ℹ️ No hay surebet válida en este momento.</b><br>La calculadora permanece oculta hasta encontrar una oportunidad.</div>';return}box.innerHTML=rows.map(o=>`<article class="surebet-opportunity"><div class="opp-head"><div><div class="eyebrow">${escSB(o.competition||'Liga no identificada')}</div><h3>${escSB(o.match||'Partido')}</h3><span class="muted">${escSB(o.market||'-')} · Línea ${escSB(o.line??'-')} · ${o.mode==='live'?'🔴 LIVE':'📅 PRE-MATCH'}</span></div><div class="margin-box"><small>MARGEN SUREBET</small><strong>${pct(o.profit_margin)}</strong></div></div><div class="odds-grid">${Object.entries(o.outcomes||{}).map(([s,q])=>`<div class="odd-card"><span>${escSB(s)}</span><b>${q.odds}</b><small>${escSB(q.bookmaker)}</small></div>`).join('')}</div><div class="calc-box">${calculator(o)}</div><div class="opp-footer"><span>Probabilidad implícita: <b>${pct(o.implied_sum)}</b> · Mezcla: <b>${escSB(o.bookmaker_mix||'-')}</b></span><button class="verify-button" onclick="verifySurebet(${Number(o.match_id)||0})">🔍 VERIFICAR CUOTAS AHORA</button></div></article>`).join('')}async function sbJson(r){let d={};try{d=await r.json()}catch(_){}if(!r.ok)throw new Error(d.detail||`HTTP ${r.status}`);return d}async function loadSurebetPre(){sbBusy(true);sb$('surebet-status').textContent=`🔄 PRE-PARTIDO · ${scopeLabel()}...`;try{const p=new URLSearchParams({limit:'100',scope:SB.scope});const d=await sbJson(await fetch('/api/v1/arbitrage/pre-match?'+p,{cache:'no-store'}));sb$('surebet-status').textContent=`📅 PRE-PARTIDO · ${d.opportunities?.length||0} oportunidades.`;renderSurebet(d)}catch(e){sb$('surebet-status').textContent='❌ Error PRE-PARTIDO: '+e.message;sb$('surebet').innerHTML='<div class="notice">❌ No se pudo cargar PRE-PARTIDO. Revisa la conexión/API.</div>'}finally{sbBusy(false)}}async function loadSurebetLive(){sbBusy(true);sb$('surebet-status').textContent=`🔄 BUSCAR AHORA · LIVE · ${scopeLabel()}...`;sb$('surebet').innerHTML='<p>Actualizando cuotas live...</p>';try{const p=new URLSearchParams({limit:'100',hours:'1',scope:SB.scope});const d=await sbJson(await fetch('/api/v1/arbitrage/live?'+p,{method:'POST',cache:'no-store'}));sb$('surebet-status').textContent=`🔴 LIVE actualizado · ${d.sync?.live_matches_seen||0} partidos · ${d.sync?.odds_saved||0} cuotas · ${d.opportunities?.length||0} surebets.`;renderSurebet(d)}catch(e){sb$('surebet-status').textContent='❌ Error EN VIVO: '+e.message;sb$('surebet').innerHTML='<div class="notice">❌ No se pudo consultar LIVE. Revisa OddsPapi/conexión.</div>'}finally{sbBusy(false)}}async function verifySurebet(id){if(!id)return;sb$('surebet-status').textContent='🔍 Verificando nuevamente las cuotas...';try{const p=new URLSearchParams({limit:'100',scope:SB.scope});const d=await sbJson(await fetch(`/api/v1/arbitrage/verify/${id}?`+p,{method:'POST',cache:'no-store'}));sb$('surebet-status').textContent=d.surebet_confirmed?'✅ SUREBET CONFIRMADA · las cuotas siguen permitiendo arbitraje.':'⚠️ LA SUREBET DESAPARECIÓ · las cuotas cambiaron.';renderSurebet(d)}catch(e){sb$('surebet-status').textContent='❌ Error al verificar: '+e.message}}function applyLeagueFilter(){if(SB.data)renderSurebet(SB.data)}setSurebetScope('peru');window.addEventListener('DOMContentLoaded',()=>{setSurebetScope('peru');loadSurebetPre()});'''

_PROVIDER_CARD='''<div class="profile-card provider-status-card"><div class="profile-title"><h2>🔌 Conexión API</h2><span id="providerStatusBadge" class="eyebrow">CARGANDO</span></div><div class="profile-grid"><div class="profile-item">PROVEEDOR<b id="dashProvider">—</b></div><div class="profile-item">ESTADO<b id="dashConnection">—</b></div><div class="profile-item">PLAN<b id="dashPlan">—</b></div><div class="profile-item">SOLICITUDES<b id="dashUsage">—</b></div><div class="profile-item">SUSCRIPCIÓN<b id="dashSubscription">—</b></div><div class="profile-item">KEY<b id="dashKey">—</b></div></div><div class="profile-actions"><a class="small-button" href="/provider-accounts">⚙️ CONFIGURAR PROVEEDORES</a></div></div>'''
_PROVIDER_JS=r'''async function loadProviderStatus(){try{const r=await fetch('/api/v1/provider-accounts/status',{cache:'no-store'});const d=await r.json();if(!d.connected){document.getElementById('providerStatusBadge').textContent='NO CONECTADO';document.getElementById('dashConnection').textContent='🔴';return}const a=d.account||{},u=d.usage||{};document.getElementById('providerStatusBadge').textContent='CONECTADO';document.getElementById('dashProvider').textContent=a.label||a.provider||'—';document.getElementById('dashConnection').textContent='🟢 CONECTADO';document.getElementById('dashPlan').textContent=d.plan||'—';document.getElementById('dashUsage').textContent=u.display||'—';document.getElementById('dashSubscription').textContent=d.subscription_status||'—';document.getElementById('dashKey').textContent=a.api_key_masked||'••••••••'}catch(e){const x=document.getElementById('dashConnection');if(x)x.textContent='⚠️ SIN VERIFICAR'}}
'''

def dashboard_response(today:date)->HTMLResponse:
    if not active_account(): return provider_accounts_page()
    html=dashboard_html(today)
    html,n=re.subn(r'<section class="welcome">.*?</section>', '<section class="welcome"><div class="welcome-card"><div class="eyebrow">Bienvenidos a ANALISYS BETSTOTAL</div><div id="dailyQuote" class="quote">Cargando frase inspiradora del día...</div><div id="quoteMeta" class="quote-meta">La frase se actualiza diariamente desde Internet.</div></div>'+_PROVIDER_CARD+'</section>',html,count=1,flags=re.S)
    html=re.sub(r'<div class="quick-title">ACCESOS RÁPIDOS</div><div class="quick-grid">.*?</div>', '<div class="quick-title">ACCESOS RÁPIDOS</div>', html, count=1, flags=re.S)
    html,n=re.subn(r'<div class="card" id="surebet-section">.*?(?=<div class="card" id="final-section">)',_CARD+'\n',html,count=1,flags=re.S)
    if n==0: html=re.sub(r'<div class="card"><div class="section-title"><h2>💰 Surebet</h2>.*?(?=<div class="card" id="final-section">)',_CARD+'\n',html,count=1,flags=re.S)
    html=re.sub(r'function renderSurebet\(.*?async function loadFinal\(',_JS+'\nasync function loadFinal(',html,count=1,flags=re.S)
    html=html.replace('</script>',_PROVIDER_JS+'\nloadProviderStatus();\n</script>',1)
    css='''.metric{background:#f4f6fa;border-radius:10px;padding:10px}.metric span{display:block;font-size:10px;color:#68758a;font-weight:800}.metric b{font-size:19px;display:block;margin-top:4px}.surebet-scope{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0}.surebet-scope button{border:1px solid #dfe5ee;border-radius:9px;padding:9px 12px;background:white;font-weight:800;cursor:pointer}.surebet-scope button.active{border:2px solid #2563eb;background:#eff6ff}.surebet-filters{margin:10px 0}.surebet-filters select{padding:8px;border-radius:8px;border:1px solid #ccd6e5}.surebet-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:12px 0}.surebet-opportunity{border:1px solid #dfe5ee;border-radius:14px;padding:16px;margin:14px 0;background:#fff}.opp-head{display:flex;justify-content:space-between;gap:15px}.opp-head h3{margin:5px 0;font-size:20px}.margin-box{background:#ecfdf5;border-radius:10px;padding:10px;text-align:center;min-width:120px}.margin-box small{display:block;font-size:10px}.margin-box strong{font-size:23px;color:#0f8a62}.odds-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:14px 0}.odd-card{border:1px solid #e5eaf1;border-radius:10px;padding:11px;background:#f8fafc}.odd-card span,.odd-card small{display:block}.odd-card b{display:block;font-size:23px;margin:3px 0}.calc-box{border-top:1px solid #e5eaf1;padding-top:12px}.calc-title{font-size:12px;font-weight:900;margin:10px 0 7px}.calc-table th,.calc-table td{font-size:12px;padding:7px}.opp-footer{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-top:12px;font-size:12px}.empty-surebet{padding:20px;border:1px dashed #ccd6e5;border-radius:12px;text-align:center}.provider-status-card .small-button{display:inline-block;text-decoration:none;border:1px solid #dfe5ee;border-radius:9px;padding:8px 10px;color:#172033;background:#fff;font-weight:800}@media(max-width:700px){.surebet-summary,.odds-grid{grid-template-columns:1fr}.opp-head,.opp-footer{flex-direction:column;align-items:stretch}}'''
    html=html.replace('</style>',css+'</style>',1)
    return HTMLResponse(html)
